def render_comment(author, body):
    """Render a comment as an HTML snippet."""
    def clean(s):
        return s.replace("<", "&lt;").replace(">", "&gt;")

    author = clean(author)
    body = clean(body)
    return (
        f"<div class=\"comment\">"
        f"<span class=\"author\">{author}</span>"
        f"<p>{body}</p>"
        f"</div>"
    )
